mapper.select:
select count(1)
from privacy_delete_job
where tenant_id = #{tenantId}
  and app_id = #{appId}

  and user_id = #{userId}


  and status = #{status}

select job_id,
       tenant_id,
       app_id,
       user_id,
       scope,
       status,
       affected_count,
       requested_by,
       reason,
       created_at
from privacy_delete_job
where tenant_id = #{tenantId}
  and app_id = #{appId}

  and user_id = #{userId}


  and status = #{status}

order by created_at desc, job_id desc
limit #{limit}
offset #{offset}
